"""Commented source ownership of temporary duration and container masks."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xA01F,0xA021,'data','Costo temporaneo globale: byte basso e alto'),(0x9AF1,0x9AF4,'code','Cab furioso: durata nel byte basso'),(0x9AF4,0x9AF6,'data','Cab normale: intestazione della regola, non codice'),(0x9AF6,0x9B0A,'code','Viaggio cab: durata pubblicata prima della partenza'),(0xA0B0,0xA0CA,'code','Scheduler: costo zero ripete; costo nonzero aggiorna la scadenza'),(0xB0AC,0xB0D7,'code','LOAD/QUIT e SAVE: costo temporaneo uno'),(0xB0EE,0xB0FD,'code','Limite del nastro originale: A01F e A020 sono fuori dal blocco salvato'),(0xC9F2,0xCA0C,'code','Regola eseguita: costo dal nibble alto prima del corpo'),(0xCC71,0xCC94,'code','Ingresso del passo DOMAIN: azzera entrambi i byte del costo'),(0xCD82,0xCD95,'code','Yield e budget fallimenti: costo uno'),(0xD7D0,0xD7D9,'code','Ritorno dell’azione del giocatore: controlla entrambi i byte del costo'),(0xDDC2,0xDDCB,'code','Ritardo dinamico: modifica solo il byte basso'),(0xDDD4,0xDE48,'code','WAIT UNTIL: differenza unsigned sull’orologio a dodici ore'),(0xE432,0xE43B,'data','Uscita dai contenitori: intestazione con maschere, non codice'),(0xE43B,0xE44C,'code','Uscita dal contenitore: ripristina il genitore esterno')]
notes={0x9AF4:'Intestazione04 00: classe locazione4, costo iniziale0. Il corpo da9AF6 sostituisce il costo con la durata del percorso.',0xA01F:'Word condivisa, non durata locale di un personaggio. CC74 azzera; CA09 assegna il costo del body selezionato; i corpi possono sovrascriverla. Il runtime conserva i due byte e la loro validità anche nei salvataggi JS.',0x9AF1:'Durata furiosa calcolata nel byte L, dopo SUB 2: il prestito non si propaga a H.',0x9B07:'Durata del cab pubblicata prima del trasferimento del veicolo e dei suoi annunci. Non aspettare il ritorno dell’azione per aggiornare la word.',0xA0B3:'Lo scheduler legge la word condivisa: costo zero ripete lo stesso attore. Un byte alto nonzero conta anche quando il basso è zero.',0xA0C3:'La durata si somma alla scadenza precedente, non al tick globale attuale.',0xB0BD:'Richiesta LOAD/QUIT: costo uno dopo il reset del clock.',0xB0CC:'SAVE imposta uno. Il formato JSON del prototipo è un adattatore che conserva anche gli ingressi temporanei della casualità.',0xB0F2:'Il blocco nastro è [840B,A01F): esclude la word temporanea. Non trattare un vecchio SAVE nativo come inizializzazione del suo valore.',0xC9F2:'In preflight A00B=0 ritorna senza assegnare il costo e senza eseguire il corpo.',0xCA09:'Scrive H=0 e L=nibble alto dell’intestazione PRIMA di entrare nel corpo. Un corpo fallito non ripristina da solo il costo precedente.',0xCC74:'Reset a ogni ingresso CC78. Non azzerare a ogni minuto: durante la visita successiva il costo può essere sostituito da altri attori.',0xCD85:'Yield esplicito: word uno prima della continuazione comune.',0xCD8E:'Autoloop fallito o budget di dieci tentativi: word uno prima di D026.',0xD7D0:'Anche il predicato che verifica il tempo dell’azione osserva la word condivisa.',0xDDC5:'Scrittura di un solo byte. Il byte alto conserva il valore precedente; nel normale percorso la precedente intestazione CA09 lo ha azzerato.',0xDDD4:'Il valore grezzo A02F contiene ore, minuti e i tag am/pm. Non usare una conversione moderna a data civile.',0xDDDA:'Maschera i tag prima della moltiplicazione per sessanta. DE48 tratta ore zero come 256 iterazioni DJNZ.',0xDE21:'Sottrazione a sedici bit; le aggiunte di 720 mantengono il wrap unsigned.',0xDE42:'Scrive entrambe le celle, anche per attese oltre 255 minuti. I passi NPC successivi le riscrivono secondo le loro regole.',0xE432:'Header 78 20: costo due, predicato E420; controllo10: richiede attributo80 e almeno uno dei bit28. Un cab in corsa perde80 e non consente di scendere.',0xE43B:'Il corpo si raggiunge solo dopo predicato e maschere. La selezione dell’oggetto può già avere aggiornato gli argomenti anche se il corpo viene rifiutato.'}
lines=['; Analisi offline, dati distinti dal codice; nessuna esecuzione Z80 nel motore JS.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=b-at;op='DEFB '+','.join(f'${v:02X}'for v in m[at:b])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/temporary-cost';root.mkdir(exist_ok=True)
(root/'temporary-cost.asm').write_text('\n'.join(lines)+'\n')
(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=122 if k=='data'else 92,**({'fields':([['Word','2 byte','A01F basso; A020 alto. Stato temporaneo condiviso, con proprietà indipendente dei due byte']]if a==0xA01F else [['Header','2 byte','Classe4, costo iniziale0; durata sostituita dal corpo9AF6']]if a==0x9AF4 else [['Header','9 byte','Costo2, predicato E420, maschere su attributi:80 richiesto e almeno un bit28']])}if k=='data'else{}))for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
